-- Isolated local fixtures. Every statement is rolled back.
begin;
set local statement_timeout='30s';
do $$
declare owner_user uuid:=gen_random_uuid(); guest uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); viewer uuid:=gen_random_uuid();
 w uuid; other_w uuid; obj uuid; other_obj uuid; rec uuid; other_rec uuid; portal uuid; foreign_portal uuid; paused uuid; result jsonb; summary jsonb; n integer;
begin
 insert into auth.users(id,email,aud,role,email_confirmed_at) select u,'portal-test-'||u||'@example.invalid','authenticated','authenticated',now() from unnest(array[owner_user,guest,outsider,viewer]) u;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 w:=public.create_workspace('Portal local fixture');other_w:=public.create_workspace('Second portal fixture');
 select id into obj from public.objects where workspace_id=w and slug='companies';select id into other_obj from public.objects where workspace_id=other_w and slug='companies';
 insert into public.records(workspace_id,object_id,display_name) values(w,obj,'Client') returning id into rec;
 insert into public.records(workspace_id,object_id,display_name) values(other_w,other_obj,'Private foreign client') returning id into other_rec;
 insert into public.portals(workspace_id,record_id,name) values(w,rec,'Client Alpha') returning id into portal;
 insert into public.portals(workspace_id,record_id,name) values(other_w,other_rec,'Secret foreign portal') returning id into foreign_portal;
 insert into public.portals(workspace_id,record_id,name,enabled) values(w,rec,'Paused portal',false) returning id into paused;
 insert into public.portal_members(workspace_id,portal_id,email,user_id) values(w,portal,'portal-test-'||guest||'@example.invalid',guest),(w,portal,'portal-test-'||owner_user||'@example.invalid',owner_user);
 insert into public.memberships(workspace_id,user_id,role) values(w,viewer,'viewer');
 insert into public.portal_items(workspace_id,portal_id,title,type,status,due_date) values(w,portal,'Planning','step','done',null),(w,portal,'Review','step','open','2026-11-01T10:00:00Z'),(w,portal,'Scope decision','decision','open',null),(w,portal,'Shared file','document','open',null),(other_w,foreign_portal,'Secret content','step','open',null);
 insert into public.portal_comments(workspace_id,portal_id,content,author_id) values(w,portal,'A shared message',owner_user);
 if has_function_privilege('anon','public.portal_directory(text,integer,text)','execute') or has_function_privilege('anon','public.portal_summaries(uuid[])','execute') then raise exception 'Anonymous portal RPC granted';end if;
 if exists(select 1 from pg_proc where oid in ('public.portal_directory(text,integer,text)'::regprocedure,'public.portal_summaries(uuid[])'::regprocedure) and prosecdef) then raise exception 'Portal RPC bypasses RLS';end if;
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',guest::text,true);
 result:=public.portal_directory();
 if (result->>'count')::integer<>1 or result->'data'->0->>'id'<>portal::text or result->'data'->0->>'access'<>'client' or result->'manage_workspace_id'<>'null'::jsonb or result->'data'->0->'workspace_id'<>'null'::jsonb then raise exception 'Guest directory leaked workspace or foreign portal %',result;end if;
 summary:=result->'data'->0->'summary';
 if (summary->>'step_count')::integer<>2 or (summary->>'completed_steps')::integer<>1 or (summary->>'document_count')::integer<>1 or (summary->>'open_decisions')::integer<>1 or (summary->>'comment_count')::integer<>1 or not (summary->>'can_comment')::boolean then raise exception 'Actual summary or guest comment permission failed %',summary;end if;
 if exists(select 1 from public.portal_members where portal_id=portal and user_id<>guest) then raise exception 'Other participant ACL exposed to guest';end if;
 if public.portal_summaries(array[foreign_portal])<>'[]'::jsonb then raise exception 'Foreign summary leaked';end if;
 insert into public.portal_comments(workspace_id,portal_id,content,author_id) values(w,portal,'Guest message',guest);
 begin insert into public.portal_comments(workspace_id,portal_id,content,author_id) values(other_w,foreign_portal,'Forged',guest);raise exception 'Guest posted across tenant';exception when insufficient_privilege then null;end;
 begin insert into public.portal_comments(workspace_id,portal_id,content,author_id) values(w,portal,'Forged author',owner_user);raise exception 'Guest forged author';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if (public.portal_directory()->>'count')::integer<>0 or public.portal_summaries(array[portal,foreign_portal])<>'[]'::jsonb then raise exception 'Uninvited user read portal';end if;
 perform set_config('request.jwt.claim.sub',viewer::text,true);
 if (public.portal_directory()->>'count')::integer<>0 then raise exception 'Limited reader bypassed record scope';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 result:=public.portal_directory('Alpha');if (result->>'count')::integer<>1 or not (result->'data'->0->>'can_manage')::boolean then raise exception 'Team-owned portal missing';end if;
 if (public.portal_directory('',0,'paused')->>'count')::integer<>1 then raise exception 'Paused filter failed';end if;
 if (public.portal_directory('%')->>'count')::integer<>0 then raise exception 'Search wildcard treated as syntax';end if;
 begin perform public.portal_directory('',-1);raise exception 'Negative page accepted';exception when invalid_parameter_value then null;end;
 begin perform public.portal_summaries(array_fill(portal,array[51]));raise exception 'Unbounded summary accepted';exception when invalid_parameter_value then null;end;
 update public.portal_members set can_comment=false where portal_id=portal;
 perform set_config('request.jwt.claim.sub',guest::text,true);
 if (public.portal_summaries(array[portal])->0->>'can_comment')::boolean then raise exception 'Revoked commenting permission retained';end if;
 begin insert into public.portal_comments(workspace_id,portal_id,content,author_id) values(w,portal,'No permission',guest);raise exception 'Read-only guest posted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);update public.portal_members set expires_at=now()-interval '1 second' where portal_id=portal;
 perform set_config('request.jwt.claim.sub',guest::text,true);if (public.portal_directory()->>'count')::integer<>0 then raise exception 'Expired guest retained access';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);update public.portal_members set expires_at=null,revoked=true where portal_id=portal;
 perform set_config('request.jwt.claim.sub',guest::text,true);if public.portal_summaries(array[portal])<>'[]'::jsonb then raise exception 'Revoked guest retained access';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);update public.portal_members set revoked=false where portal_id=portal;update public.portals set enabled=false where id=portal;
 perform set_config('request.jwt.claim.sub',guest::text,true);if (public.portal_directory()->>'count')::integer<>0 then raise exception 'Disabled portal still accessible';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 for n in 1..26 loop insert into public.portals(workspace_id,record_id,name) values(w,rec,'Paged portal '||n);end loop;
 result:=public.portal_directory('Paged portal',0);if jsonb_array_length(result->'data')<>24 or (result->>'count')::integer<>26 then raise exception 'Directory not bounded';end if;
 result:=public.portal_directory('Paged portal',1);if jsonb_array_length(result->'data')<>2 then raise exception 'Directory pagination failed';end if;
 perform set_config('request.jwt.claim.sub','',true);begin perform public.portal_directory();raise exception 'Missing session accepted';exception when insufficient_privilege then null;end;
end $$;
rollback;
